def _x(a):
    return ((a << 1) & 255) ^ (27 if a & 128 else 0)
def _rk(k):
    w = [list(k[i*4:(i+1)*4]) for i in range(8)]
    rc = 1
    for i in range(8, 60):
        t = list(w[i-1])
        if i % 8 == 0:
            t = [_S[t[(j+1) % 4]] for j in range(4)]
            t[0] ^= rc
            rc = _x(rc)
        elif i % 8 == 4:
            t = [_S[b] for b in t]
        w.append([w[i-8][j] ^ t[j] for j in range(4)])
    return w
def _shift(s):
    for r in range(1, 4):
        s[r] = s[r][r:] + s[r][:r]
def _mix(s):
    for c in range(4):
        a, b, d, e = s[0][c], s[1][c], s[2][c], s[3][c]
        t = a ^ b ^ d ^ e
        s[0][c] ^= t ^ _x(a ^ b)
        s[1][c] ^= t ^ _x(b ^ d)
        s[2][c] ^= t ^ _x(d ^ e)
        s[3][c] ^= t ^ _x(e ^ a)
def _ark(s, w, rd):
    for c in range(4):
        for r in range(4):
            s[r][c] ^= w[rd*4 + c][r]
def _enc16(k, blk):
    w = _rk(k)
    s = [[blk[c*4 + r] for c in range(4)] for r in range(4)]
    _ark(s, w, 0)
    for rd in range(1, 14):
        for r in range(4):
            s[r] = [_S[b] for b in s[r]]
        _shift(s); _mix(s); _ark(s, w, rd)
    for r in range(4):
        s[r] = [_S[b] for b in s[r]]
    _shift(s); _ark(s, w, 14)
    return bytes(s[r][c] for c in range(4) for r in range(4))
def _ctr(k, iv, data):
    out = bytearray()
    n = int.from_bytes(iv, "big")
    for off in range(0, len(data), 16):
        ks = _enc16(k, ((n + off // 16) % (1 << 128)).to_bytes(16, "big"))
        chunk = data[off:off+16]
        out += bytes(a ^ b for a, b in zip(chunk, ks))
    return bytes(out)



